def has_cycle(next_ptrs: list[int]) -> bool:
    if not next_ptrs or next_ptrs[0] == -1:
        return False
    slow = 0
    fast = 0
    while fast != -1 and next_ptrs[fast] != -1:
        slow = next_ptrs[slow]
        fast = next_ptrs[next_ptrs[fast]]
        if slow == fast:
            return True
    return False
